1	package net.officefloor.hq.app;
2	
3	import java.util.List;
4	import java.util.Map;
5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // project references client via FK; H2 refuses TRUNCATE on a referenced table, so drop
36	        // referential integrity for the duration of the clear, then restore it.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        jdbc.execute("TRUNCATE TABLE dashboard_config");
39	        jdbc.execute("TRUNCATE TABLE note RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE project_tag RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE tag RESTART IDENTITY");
42	        jdbc.execute("TRUNCATE TABLE task RESTART IDENTITY");
43	        jdbc.execute("TRUNCATE TABLE payment RESTART IDENTITY");
44	        jdbc.execute("TRUNCATE TABLE line_item RESTART IDENTITY");
45	        jdbc.execute("TRUNCATE TABLE invoice RESTART IDENTITY");
46	        jdbc.execute("TRUNCATE TABLE project RESTART IDENTITY");
47	        jdbc.execute("TRUNCATE TABLE contact RESTART IDENTITY");
48	        jdbc.execute("TRUNCATE TABLE client RESTART IDENTITY");
49	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
50	    }
51	
52	    /**
53	     * Parse a seeded timestamp, tolerating both a full ISO-8601 instant ({@code 2026-02-01T09:00:00Z})
54	     * and a bare date ({@code 2026-02-01}, taken at the start of the day in UTC).
55	     */
56	    private static java.time.Instant parseInstant(String value) {
57	        if (value.length() == 10) {
58	            return java.time.LocalDate.parse(value).atStartOfDay(java.time.ZoneOffset.UTC).toInstant();
59	        }
60	        return java.time.Instant.parse(value);
61	    }
62	
63	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
64	    @PostMapping("/seed")
65	    @SuppressWarnings("unchecked")
66	    public void seed(@RequestBody Map<String, Object> fixture) {
67	        Object asOf = fixture.get("asOf");
68	        if (asOf != null) {
69	            // The dashboard's reference date for deciding which SENT invoices are overdue (V24).
70	            jdbc.update("INSERT INTO dashboard_config (id, as_of) VALUES (1, ?)",
71	                    java.sql.Date.valueOf(asOf.toString()));
72	        }
73	        List<Map<String, Object>> clients =
74	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
75	        for (Map<String, Object> client : clients) {
76	            jdbc.update("INSERT INTO client (id, name, email) VALUES (?, ?, ?)",
77	                    ((Number) client.get("id")).longValue(), client.get("name"), client.get("email"));
78	        }
79	        List<Map<String, Object>> projects =
80	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
81	        for (Map<String, Object> project : projects) {
82	            Object status = project.getOrDefault("status", "ACTIVE");
83	            boolean archived = Boolean.TRUE.equals(project.getOrDefault("archived", Boolean.FALSE));
84	            Object budgetValue = project.get("budget");
85	            java.math.BigDecimal budget = budgetValue == null ? java.math.BigDecimal.ZERO
86	                    : new java.math.BigDecimal(budgetValue.toString());
87	            Object code = project.getOrDefault("code", "");
88	            jdbc.update(
89	                    "INSERT INTO project (id, name, client_id, status, archived, budget, code) "
90	                            + "VALUES (?, ?, ?, ?, ?, ?, ?)",
91	                    ((Number) project.get("id")).longValue(), project.get("name"),
92	                    ((Number) project.get("clientId")).longValue(), status, archived, budget,
93	                    code == null ? "" : code.toString());
94	        }
95	        List<Map<String, Object>> tasks =
96	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
97	        for (Map<String, Object> task : tasks) {
98	            Object done = task.getOrDefault("done", Boolean.FALSE);
99	            jdbc.update("INSERT INTO task (id, project_id, title, done) VALUES (?, ?, ?, ?)",
100	                    ((Number) task.get("id")).longValue(),
101	                    ((Number) task.get("projectId")).longValue(), task.get("title"),
102	                    Boolean.TRUE.equals(done));
103	        }
104	        List<Map<String, Object>> notes =
105	                (List<Map<String, Object>>) fixture.getOrDefault("notes", List.of());
106	        long maxNoteId = 0;
107	        for (Map<String, Object> note : notes) {
108	            long noteId = ((Number) note.get("id")).longValue();
109	            maxNoteId = Math.max(maxNoteId, noteId);
110	            jdbc.update(
111	                    "INSERT INTO note (id, target_type, target_id, body, at) VALUES (?, ?, ?, ?, ?)",
112	                    noteId, note.get("targetType"),
113	                    ((Number) note.get("targetId")).longValue(), note.get("text"),
114	                    java.sql.Timestamp.from(parseInstant(note.get("at").toString())));
115	        }
116	        if (maxNoteId > 0) {
117	            // Seeding explicit ids does not advance H2's IDENTITY sequence, so a note created later
118	            // through the API would collide on id=1. Nudge the sequence past the seeded ids.
119	            jdbc.execute("ALTER TABLE note ALTER COLUMN id RESTART WITH " + (maxNoteId + 1));
120	        }
121	        List<Map<String, Object>> tags =
122	                (List<Map<String, Object>>) fixture.getOrDefault("tags", List.of());
123	        for (Map<String, Object> tag : tags) {
124	            jdbc.update("INSERT INTO tag (id, name) VALUES (?, ?)",
125	                    ((Number) tag.get("id")).longValue(), tag.get("name"));
126	        }
127	        List<Map<String, Object>> projectTags =
128	                (List<Map<String, Object>>) fixture.getOrDefault("projectTags", List.of());
129	        for (Map<String, Object> projectTag : projectTags) {
130	            jdbc.update("INSERT INTO project_tag (project_id, tag_id) VALUES (?, ?)",
131	                    ((Number) projectTag.get("projectId")).longValue(),
132	                    ((Number) projectTag.get("tagId")).longValue());
133	        }
134	        List<Map<String, Object>> contacts =
135	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
136	        for (Map<String, Object> contact : contacts) {
137	            boolean primary = Boolean.TRUE.equals(contact.getOrDefault("primary", Boolean.FALSE));
138	            jdbc.update(
139	                    "INSERT INTO contact (id, client_id, name, email, role, is_primary) "
140	                            + "VALUES (?, ?, ?, ?, ?, ?)",
141	                    ((Number) contact.get("id")).longValue(),
142	                    ((Number) contact.get("clientId")).longValue(), contact.get("name"),
143	                    contact.get("email"), contact.get("role"), primary);
144	        }
145	        List<Map<String, Object>> invoices =
146	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
147	        for (Map<String, Object> invoice : invoices) {
148	            Object status = invoice.getOrDefault("status", "DRAFT");
149	            Object issuedDate = invoice.get("issuedDate");
150	            Object dueDate = invoice.get("dueDate");
151	            long invoiceId = ((Number) invoice.get("id")).longValue();
152	            // An invoice's amount is the sum of its line items (quantity times unit price); work it
153	            // out here so a fixture lists the things being charged for, not a pre-computed figure.
154	            // A fixture may still pass an explicit amount for an invoice with no line items.
155	            List<Map<String, Object>> lineItems =
156	                    (List<Map<String, Object>>) invoice.getOrDefault("lineItems", null);
157	            java.math.BigDecimal amount;
158	            if (lineItems != null) {
159	                amount = java.math.BigDecimal.ZERO;
160	                for (Map<String, Object> lineItem : lineItems) {
161	                    java.math.BigDecimal unitPrice =
162	                            new java.math.BigDecimal(lineItem.get("unitPrice").toString());
163	                    int qty = ((Number) lineItem.get("qty")).intValue();
164	                    amount = amount.add(unitPrice.multiply(java.math.BigDecimal.valueOf(qty)));
165	                }
166	            } else {
167	                lineItems = List.of();
168	                Object explicit = invoice.get("amount");
169	                amount = explicit == null ? java.math.BigDecimal.ZERO
170	                        : new java.math.BigDecimal(explicit.toString());
171	            }
172	            Object discountPct = invoice.getOrDefault("discountPct", 0);
173	            Object taxPct = invoice.getOrDefault("taxPct", 0);
174	            jdbc.update(
175	                    "INSERT INTO invoice "
176	                            + "(id, project_id, amount, status, issued_date, due_date, discount_pct, "
177	                            + "tax_pct) "
178	                            + "VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
179	                    invoiceId, ((Number) invoice.get("projectId")).longValue(), amount, status,
180	                    issuedDate == null ? null : java.sql.Date.valueOf(issuedDate.toString()),
181	                    dueDate == null ? null : java.sql.Date.valueOf(dueDate.toString()),
182	                    ((Number) discountPct).intValue(), ((Number) taxPct).intValue());
183	            for (Map<String, Object> lineItem : lineItems) {
184	                Object unit = lineItem.getOrDefault("unit", "");
185	                jdbc.update(
186	                        "INSERT INTO line_item "
187	                                + "(id, invoice_id, description, quantity, unit, unit_price) "
188	                                + "VALUES (?, ?, ?, ?, ?, ?)",
189	                        ((Number) lineItem.get("id")).longValue(), invoiceId,
190	                        lineItem.get("description"),
191	                        ((Number) lineItem.get("qty")).intValue(),
192	                        unit == null ? "" : unit.toString(),
193	                        new java.math.BigDecimal(lineItem.get("unitPrice").toString()));
194	            }
195	        }
196	        List<Map<String, Object>> payments =
197	                (List<Map<String, Object>>) fixture.getOrDefault("payments", List.of());
198	        long maxPaymentId = 0;
199	        for (Map<String, Object> payment : payments) {
200	            long paymentId = ((Number) payment.get("id")).longValue();
201	            maxPaymentId = Math.max(maxPaymentId, paymentId);
202	            jdbc.update(
203	                    "INSERT INTO payment (id, invoice_id, amount, paid_date) VALUES (?, ?, ?, ?)",
204	                    paymentId, ((Number) payment.get("invoiceId")).longValue(),
205	                    new java.math.BigDecimal(payment.get("amount").toString()),
206	                    java.sql.Date.valueOf(payment.get("date").toString()));
207	        }
208	        if (maxPaymentId > 0) {
209	            // Seeding explicit ids does not advance H2's IDENTITY sequence, so a payment created later
210	            // through the API would collide on id=1. Nudge the sequence past the seeded ids.
211	            jdbc.execute("ALTER TABLE payment ALTER COLUMN id RESTART WITH " + (maxPaymentId + 1));
212	        }
213	    }
214	}
