import React, { useEffect, useState } from 'react';

// The invoices feature owns its own state and data loading (no global store). One place that lists
// every invoice across all projects, showing which project each one is for (the project's NAME, a
// cross-entity join surfaced in the UI) and the stage (status) it is at. Served by /api/invoices.
type AllInvoice = {
  id: number;
  projectId: number;
  projectName: string;
  amount: number;
  status: string;
};

function formatAmount(amount: number): string {
  return `$${Number(amount).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}

const PAGE_SIZE = 10;

export function AllInvoicesPage() {
  const [invoices, setInvoices] = useState<AllInvoice[]>([]);
  const [statusFilter, setStatusFilter] = useState('');
  // The full list is large, so it is shown a page at a time with next/previous controls.
  const [page, setPage] = useState(1);

  useEffect(() => {
    async function load() {
      const res = await fetch('/api/invoices');
      setInvoices(await res.json());
    }
    void load();
  }, []);

  // Distinct stages present, so the filter offers exactly the stages the list can show.
  const statuses = Array.from(new Set(invoices.map((inv) => inv.status))).sort();
  const filtered = statusFilter
    ? invoices.filter((inv) => inv.status === statusFilter)
    : invoices;

  // Clamp the page to the available range so changing the filter can't strand us on an empty page.
  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const start = (currentPage - 1) * PAGE_SIZE;
  const visible = filtered.slice(start, start + PAGE_SIZE);

  return (
    <section data-testid="invoices-section">
      <h1>Invoices</h1>

      <label>
        Stage
        <select
          data-testid="invoice-status-filter"
          value={statusFilter}
          onChange={(e) => {
            setStatusFilter(e.target.value);
            setPage(1);
          }}
        >
          <option value="">All</option>
          {statuses.map((status) => (
            <option key={status} value={status}>
              {status}
            </option>
          ))}
        </select>
      </label>

      {filtered.length === 0 ? (
        <p data-testid="all-invoices-empty">No invoices yet.</p>
      ) : (
        <table data-testid="all-invoices-table">
          <thead>
            <tr>
              <th>Job</th>
              <th>Amount</th>
              <th>Stage</th>
            </tr>
          </thead>
          <tbody>
            {visible.map((inv) => (
              <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
                <td data-testid="invoice-project">{inv.projectName}</td>
                <td data-testid="invoice-amount">{formatAmount(inv.amount)}</td>
                <td data-testid="invoice-status">{inv.status}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <nav data-testid="invoice-pagination">
        <button
          type="button"
          data-testid="invoice-page-prev"
          disabled={currentPage <= 1}
          onClick={() => setPage((p) => Math.max(1, p - 1))}
        >
          Previous
        </button>
        <span data-testid="invoice-page-label">{currentPage}</span>
        <button
          type="button"
          data-testid="invoice-page-next"
          disabled={currentPage >= pageCount}
          onClick={() => setPage((p) => Math.min(pageCount, p + 1))}
        >
          Next
        </button>
      </nav>
    </section>
  );
}

